// Monta o payload da Conversions API para cada lead da fila.
//
// Dois caminhos possiveis:
//   1) COM ctwa_clid  -> atribuicao direta ao clique do anuncio (ideal)
//   2) SEM ctwa_clid  -> Advanced Matching por telefone/email hasheados
//                        (nao atribui ao clique, mas alimenta publico
//                         personalizado e lookalike)
//
// Os hashes ja vem prontos do Postgres (SHA-256, minusculo, sem espaco).

const GRAPH_VERSION = 'v26.0';
const saida = [];

for (const item of $input.all()) {
  const d = item.json;

  // Meta rejeita eventos com mais de 7 dias.
  const agora = Math.floor(Date.now() / 1000);
  const seteDias = 7 * 24 * 60 * 60;
  let eventTime = Number(d.event_time);
  if (!eventTime || agora - eventTime > seteDias) {
    eventTime = agora;
  }

  const userData = {
    page_id: String(d.page_id)
  };

  const temClid = d.ctwa_clid && String(d.ctwa_clid).trim() !== '';

  if (temClid) {
    // NAO hashear o ctwa_clid.
    userData.ctwa_clid = String(d.ctwa_clid).trim();
  }

  // Hashes sempre ajudam no match, com ou sem clid.
  if (d.phone_hash) userData.ph = [d.phone_hash];
  if (d.email_hash) userData.em = [d.email_hash];

  const evento = {
    event_name: d.event_name || 'Lead',
    event_time: eventTime,
    event_id: d.event_id,
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    user_data: userData
  };

  // custom_data so faz sentido quando ha valor (ex.: evento Purchase).
  if (d.valor !== null && d.valor !== undefined && Number(d.valor) > 0) {
    evento.custom_data = {
      currency: d.moeda || 'BRL',
      value: Number(d.valor)
    };
  }

  saida.push({
    json: {
      lead_id: d.lead_id,
      event_id: d.event_id,
      tem_clid: temClid,
      url: `https://graph.facebook.com/${GRAPH_VERSION}/${d.dataset_id}/events`,
      access_token: d.access_token,
      corpo: {
        data: [evento],
        partner_agent: 'trafego_academy_n8n'
      }
    }
  });
}

return saida;

const fila = $('Buscar fila no Supabase').all().map((item) => item.json);
const saida = [];
for (const item of $input.all()) {
  const origem = fila.find((lead) => lead.lead_id === item.json.lead_id);
  if (!origem?.ctwa_clid || !origem?.waba_id) continue;
  const evento = { ...item.json.corpo.data[0],
    event_name: origem.event_name || 'LeadSubmitted',
    user_data: {
      whatsapp_business_account_id: String(origem.waba_id),
      ctwa_clid: String(origem.ctwa_clid).trim()
    }
  };
  saida.push({ json: { ...item.json, corpo: { ...item.json.corpo, data: [evento] } } });
}
return saida;

// Interpreta a resposta do Meta e prepara o retorno para o Supabase.
// Como 'neverError' esta ligado, erro HTTP tambem chega aqui em vez de
// derrubar a execucao - o que permite gravar o motivo no banco.

const resp = $json;
const contexto = $('Um lead por vez').item.json;

const status = resp.statusCode ?? 0;
const corpo = resp.body ?? resp;

let ok = false;
let mensagem = '';

if (status >= 200 && status < 300) {
  const recebidos = corpo?.events_received ?? 0;
  ok = recebidos > 0;
  mensagem = ok
    ? `OK events_received=${recebidos} fbtrace=${corpo?.fbtrace_id ?? '-'}`
    : `HTTP 200 porem events_received=0 | ${JSON.stringify(corpo).slice(0, 500)}`;
} else {
  const err = corpo?.error ?? {};
  mensagem = `HTTP ${status} | code=${err.code ?? '-'} sub=${err.error_subcode ?? '-'} | ${err.message ?? JSON.stringify(corpo).slice(0, 400)}`;
}

return [{
  json: {
    lead_id: contexto.lead_id,
    event_id: contexto.event_id,
    tem_clid: contexto.tem_clid,
    ok,
    mensagem
  }
}];
